#!/bin/bash
# Paper simulations: which command with which arguments (the reproducible content of the former one-night queue scripts).
# Every step is resumable (run_all.py skips finished steps). Movies are generated by gen_density.py / gen_hollow.py /
# gen_moving.py (see their docstrings); outputs under <out root>/papersim.
#
# usage: CUDA_VISIBLE_DEVICES=<gpu> bash analysis/papersim/reproduce.sh <what> "<items>"
#   density "D0.5 D1 D2 D4"          realistic-PSF density sweep (60 000 frames): SMLM / SIMFLUX, DECODE, SIMCODE preprint
#                                    (v1), SIMCODE v2 (set m1809), metrics
#   gauss "D1_gauss D4_gauss ..."    the preprint's conditions (Gaussian sigma 1.3 px PSF): baselines as the preprint ran
#                                    them (DECODE = the preprint's model), v1, then v2 with the set g13, metrics
#   hollow "<cond:R:scale> ..."      hollow microtubules, 120 000 frames, e.g. "1809_2:25:1 1809_2:25:2 1809_2:25:8"
#                                    (x1: all methods; other photon levels: v2 + DECODE only, env HOLLOW_STEPS to change)
#   s10 "m1809 g13"                  isolated-emitter precision vs CRLB table per network set
#   v2 "D1 Dexp1 D1_gauss ..."       SIMCODE v2 + metrics + GT-FRC only, next to the earlier v2 (movies / baselines / v1
#                                    unchanged): model m1809 (g13 for *_gauss), output <run>/v2_<model>${V2TAG} (default
#                                    V2TAG=_3d), metrics_<model>${V2TAG}.json, gtfrc_<model>${V2TAG}.json (ref = the earlier v2)
#   v2psf_movies                     (2026-11-15) the v2-PSF movie sets D<d>_v2psf (gen_density.py --psf v2) and Dexp<d>_v2psf
#                                    (gen_hollow.py --radius_nm 0 --v2psf 1): in-situ PSF v2, v2 camera, heights from the v2 calib
#   v2psf_decode                     DECODE retrain for them (dec_sim1809v2; out/papersim/decode_v2psf/train_dec_sim1809v2.sh, hours)
#   v2psf "D1 Dexp1 ..."             all methods on <item>_v2psf: SMLM / SIMFLUX with the v2 PSF, SIMCODE v1 (+ GT pattern), DECODE
#                                    dec_sim1809v2, SIMCODE v2 (MODEL = a models.json name or a model folder, NAME = its output
#                                    name, default m1809 / m1809v2), metrics, GT-FRC; reference = the previous m1809 (old-PSF
#                                    networks, models/archive_psf_v1/m1809) as v2_m1809psf1 (REF)
#   v2psf_figs                       overview / fig_density / summaries / time to fidelity of the v2-PSF sets (NAME as above)
#   moving_v2psf                     (2026-11-15) moving microtubules with the v2 PSF / camera at the experimental photons
#                                    (gen_moving.py --cond 1809_2 --v2psf 1 -> moving_exp_v2psf): SMLM / SIMFLUX (PSF v2), DECODE
#                                    dec_sim1809v2, SIMCODE v1, SIMCODE v2 (MODEL / NAME as v2psf), metrics, moving_matched, and the SI
#                                    figures fig_moving_pp.py (preprint layout) -> out/paper_figs_v2/si_simulated_live_smlm{,_internal}.*
#                                    and fig_moving_main.py (extended)
#   s10_v2psf "m1809"                S10 precision vs CRLB on the in-situ PSF v2 (s10.py --psf v2 -> s10_<model>v2) + si_crlb_figure.py (extended) + si_crlb_figure_pp.py (preprint layout)
#   wsm_movies "Dexp D"              (2026-11-15) the webSMLM-GT sets <P><d>_v2psf_wsm: the generator settings of <P><d>_v2psf with the
#                                    webSMLM microtubule field wsm:11:3:3 (wsm_gt.py; picked from out/papersim/websmlm_gt/candidates.png)
#   wsm "Dexp1 Dexp0.5 ..."          all methods on <item>_v2psf_wsm as v2psf (no old-PSF reference row), metrics, GT-FRC
#   wsm_figs                         Fig 2 (fig_sim_fig2.py), SI figure + table (fig_sim_main.py), overview, fig_density of the _wsm sets
#   wsm3d "<densities>"              (2026-11-15) the <P><d>_v2psf_wsm3d sets (P = Dexp default, env P=D for the preprint condition):
#                                    the wsm:11:3:3 labels at their own webSMLM heights (--gt wsm3d:11:3:3), every method as wsm with the
#                                    SMLM / SIMFLUX fit plane at the median GT height (run_wsm3d.sh; movies on the SSD, symlinked)
#   wsm3d_figs "<densities>"         common selection rule (common_rule.py), old-vs-new table (wsm3d_compare.py), Fig 2 with the common
#                                    rule and a z-coded GT (fig_sim_common.py -> out/paper_figs_v2/fig_sim_Dexp_v2psf_wsm3d.*), SI figure /
#                                    table, overview, fig_density
set -u
REPO=$(cd "$(dirname "$0")/../.." && pwd); cd "$REPO"
PY=${PY:-python}; O=${SIMCODE_OUT:-out}/papersim; mkdir -p $O/logs
disk_guard() { [ "$(df --output=avail -BG "$O" | tail -1 | tr -dc 0-9)" -ge 15 ] || { echo "less than 15 GB free: stop"; exit 1; }; }
what=$1; items=${2:-}
case $what in
  density)
    for D in $items; do
      $PY analysis/papersim/run_all.py $O/$D --steps base,decode,v1,v2,metrics --model m1809 --gt_diag 0 >> $O/logs/full_$D.log 2>&1
      echo "$(date) done $D rc $?"
    done ;;
  gauss)
    for D in $items; do
      $PY analysis/papersim/run_all.py $O/$D --steps base,decode_pre,v1,metrics --psf gauss:1.3 --model g13 >> $O/logs/full_$D.log 2>&1
      $PY analysis/papersim/run_all.py $O/$D --steps v2,metrics --model g13 --gt_diag 0 --redo metrics >> $O/logs/full_$D.log 2>&1
      rm -rf $O/$D/full/base/work
      echo "$(date) done $D rc $?"
    done ;;
  hollow)
    for spec in $items; do
      disk_guard
      IFS=: read cond R s <<< "$spec"
      d=$O/hollow120k/${cond}_R${R}_x${s}
      [ -f $d/movie.tif ] || $PY analysis/papersim/gen_hollow.py --cond $cond --radius_nm $R --phot_scale $s --nframes 120000 --out $d > $O/logs/gen120k_${cond}_R${R}_x${s}.log 2>&1
      steps=${HOLLOW_STEPS:-$([ "$s" = 1 ] && echo base,decode,v2,metrics,hollow || echo decode,v2,metrics,hollow)}
      $PY analysis/papersim/run_all.py $d --model m1809 --gt_diag 0 --steps $steps >> $O/logs/full_h120k_${cond}_R${R}_x${s}.log 2>&1
      rc=$?; rm -rf $d/full/base/work
      echo "$(date) done hollow120k $spec rc $rc"
    done ;;
  s10)
    for NS in $items; do
      if [ "$NS" = g13 ]; then $PY analysis/papersim/s10.py --model g13 --psf gauss1.3 --out $O/s10 > $O/logs/s10_$NS.log 2>&1
      else $PY analysis/papersim/s10.py --model $NS --out $O/s10 > $O/logs/s10_$NS.log 2>&1; fi
      echo "$(date) done s10 $NS rc $?"
    done ;;
  v2)
    for D in $items; do
      M=m1809; case $D in *_gauss) M=g13 ;; esac
      $PY analysis/papersim/run_all.py $O/$D --steps v2,metrics,gtfrc --model $M --gt_diag 0 --tag ${V2TAG:-_3d} --ref $M >> $O/logs/v2${V2TAG:-_3d}_$D.log 2>&1
      echo "$(date) done v2${V2TAG:-_3d} $D rc $?"
    done ;;
  v2psf_movies)
    for D in 0.5 1 2 4; do
      [ -f $O/D${D}_v2psf/gen.json ] || $PY analysis/papersim/gen_density.py --density $D --nframes 60000 --psf v2 --out $O/D${D}_v2psf > $O/logs/gen_D${D}_v2psf.log 2>&1
      [ -f $O/Dexp${D}_v2psf/gen.json ] || $PY analysis/papersim/gen_hollow.py --radius_nm 0 --density $D --nframes 60000 --v2psf 1 --out $O/Dexp${D}_v2psf > $O/logs/gen_Dexp${D}_v2psf.log 2>&1
      echo "$(date) movies D${D}_v2psf Dexp${D}_v2psf"
    done ;;
  v2psf_decode)
    bash $O/decode_v2psf/train_dec_sim1809v2.sh > $O/decode_v2psf/train_dec_sim1809v2.log 2>&1 ;;
  v2psf)
    for D in $items; do
      # reference row first (gtfrc reads it): the previous m1809 (old-PSF networks) -> v2_m1809psf1, metrics_m1809psf1.json
      $PY analysis/papersim/run_all.py $O/${D}_v2psf --steps base,v1,v1gt,decode --psf models/insitu/calib_1809_2_psf_v2.json --decode_name dec_sim1809v2 >> $O/logs/full_${D}_v2psf.log 2>&1
      $PY analysis/papersim/run_all.py $O/${D}_v2psf --steps v2,metrics --model models/archive_psf_v1/m1809 --name m1809psf1 --gt_diag 0 >> $O/logs/full_${D}_v2psf.log 2>&1
      $PY analysis/papersim/run_all.py $O/${D}_v2psf --steps v2,metrics,gtfrc --model ${MODEL:-m1809} --name ${NAME:-m1809v2} --gt_diag 0 --ref ${REF:-m1809psf1} >> $O/logs/full_${D}_v2psf.log 2>&1
      rc=$?; rm -rf $O/${D}_v2psf/full/base/work
      echo "$(date) done ${D}_v2psf rc $rc"
    done ;;
  v2psf_figs)
    N=${NAME:-m1809v2}
    for P in D Dexp; do
      $PY analysis/papersim/fig_density.py --prefix $P --suffix _v2psf --model $N
      $PY analysis/papersim/fig_gtfrc.py --prefix $P --suffix _v2psf --model $N --ref ${REF:-m1809psf1}
      $PY analysis/papersim/fig_overview.py --prefix $P --suffix _v2psf --model $N
    done ;;
  moving_v2psf)
    D=$O/moving_exp_v2psf; N=${NAME:-m1809v2}
    [ -f $D/gen.json ] || $PY analysis/papersim/gen_moving.py --cond 1809_2 --v2psf 1 --out $D > $O/logs/gen_moving_exp_v2psf.log 2>&1
    $PY analysis/papersim/run_all.py $D --steps base,decode,v1,v2,metrics --psf models/insitu/calib_1809_2_psf_v2.json --decode_name dec_sim1809v2 \
        --model ${MODEL:-m1809} --name $N --gt_diag 0 >> $O/logs/full_moving_exp_v2psf.log 2>&1
    $PY analysis/papersim/moving_matched.py $D --model $N
    $PY analysis/papersim/fig_moving_main.py --movie $D --model $N
    $PY analysis/papersim/fig_moving_pp.py --movie $D --model $N; $PY analysis/papersim/fig_moving_pp.py --movie $D --model $N --internal 1
    echo "$(date) done moving_exp_v2psf" ;;
  s10_v2psf)
    for NS in $items; do
      $PY analysis/papersim/s10.py --model $NS --psf v2 --out $O/s10 > $O/logs/s10_${NS}v2.log 2>&1
      $PY analysis/papersim/si_crlb_figure.py --tag ${NS}v2
      $PY analysis/papersim/si_crlb_figure_pp.py --tag ${NS}v2
    done ;;
  wsm_movies)
    for P in $items; do for D in 0.5 1 2 4; do
      if [ $P = Dexp ]; then [ -f $O/Dexp${D}_v2psf_wsm/gen.json ] || $PY analysis/papersim/gen_hollow.py --radius_nm 0 --density $D --nframes 60000 --v2psf 1 --gt wsm:11:3:3 --out $O/Dexp${D}_v2psf_wsm > $O/logs/gen_Dexp${D}_v2psf_wsm.log 2>&1
      else [ -f $O/D${D}_v2psf_wsm/gen.json ] || $PY analysis/papersim/gen_density.py --density $D --nframes 60000 --psf v2 --gt wsm:11:3:3 --out $O/D${D}_v2psf_wsm > $O/logs/gen_D${D}_v2psf_wsm.log 2>&1; fi
      echo "$(date) movie ${P}${D}_v2psf_wsm rc $?"
    done; done ;;
  wsm)
    for D in $items; do
      $PY analysis/papersim/run_all.py $O/${D}_v2psf_wsm --steps base,v1,v1gt,decode --psf models/insitu/calib_1809_2_psf_v2.json --decode_name dec_sim1809v2 >> $O/logs/full_${D}_v2psf_wsm.log 2>&1
      $PY analysis/papersim/run_all.py $O/${D}_v2psf_wsm --steps v2,metrics,gtfrc --model ${MODEL:-m1809} --name ${NAME:-m1809v2} --gt_diag 0 >> $O/logs/full_${D}_v2psf_wsm.log 2>&1
      rc=$?; rm -rf $O/${D}_v2psf_wsm/full/base/work
      echo "$(date) done ${D}_v2psf_wsm rc $rc"
    done ;;
  wsm_figs)
    N=${NAME:-m1809v2}
    $PY analysis/papersim/fig_sim_fig2.py --prefix Dexp --suffix _v2psf_wsm --model $N
    for P in ${items:-Dexp}; do
      $PY analysis/papersim/fig_sim_main.py --prefix $P --suffix _v2psf_wsm --model $N
      $PY analysis/papersim/fig_overview.py --prefix $P --suffix _v2psf_wsm --model $N
      $PY analysis/papersim/fig_density.py --prefix $P --suffix _v2psf_wsm --model $N
    done ;;
  wsm3d)
    bash analysis/papersim/run_wsm3d.sh "$items" ;;
  wsm3d_figs)
    N=${NAME:-m1809v2}; P=${P:-Dexp}
    for D in $items; do $PY analysis/papersim/common_rule.py --set ${P}${D}_v2psf_wsm3d,${P}${D}_v2psf_wsm --model $N; done
    $PY analysis/papersim/wsm3d_compare.py --prefix $P --densities $(echo $items | tr ' ' ',')
    [ $P = Dexp ] && $PY analysis/papersim/fig_sim_common.py --set Dexp1_v2psf_wsm3d
    $PY analysis/papersim/fig_sim_main.py --prefix $P --suffix _v2psf_wsm3d --model $N --v2key v2c
    $PY analysis/papersim/fig_sim_main.py --prefix $P --suffix _v2psf_wsm3d --model $N --v2key v2c --internal 1
    $PY analysis/papersim/fig_overview.py --prefix $P --suffix _v2psf_wsm3d --model $N
    $PY analysis/papersim/fig_density.py --prefix $P --suffix _v2psf_wsm3d --model $N ;;
  *) sed -n 2,40p "$0"; exit 1 ;;
esac
